class BIT:
    def __init__(s, n): s.t = [0] * (n + 1)
    def add(s, i, v):
        i += 1
        while i < len(s.t): s.t[i] += v; i += i & -i
    def sum(s, i):  # sum of [0, i)
        r = 0
        while i: r += s.t[i]; i -= i & -i
        return r

